import { Controller, Get, Query, Req, Injectable, Module, NestMiddleware } from '@nestjs/common';
import { Pool } from 'pg';

// Database connection pool
const pool = new Pool({
  host: process.env.DB_HOST,
  port: 5432,
  database: 'multitenant_app',
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,
  max: 20,
});

@Injectable()
export class TenantMiddleware implements NestMiddleware {
  use(req: any, res: any, next: () => void) {
    // Extract tenant from JWT - already validated by auth guard upstream
    req.tenantId = req.user?.tenantId || req.headers['x-tenant-id'];
    next();
  }
}

@Injectable()
export class OrdersService {
  async searchOrders(tenantId: string, searchTerm: string, status: string) {
    const client = await pool.connect();
    try {
      // Set the tenant context for RLS - this is the application-level control
      await client.query(`SET app.current_tenant = '${tenantId}'`);

      // Build search query with filters
      // NOTE: status is validated against enum upstream in DTO validation pipe
      // searchTerm uses parameterized query for safety
      let query = `
        SELECT o.id, o.order_number, o.total_amount, o.status, o.created_at,
               c.name as customer_name, c.email as customer_email
        FROM orders o
        JOIN customers c ON o.customer_id = c.id
        WHERE 1=1
      `;
      const params: any[] = [];
      let paramIndex = 1;

      if (searchTerm) {
        // Developer thought this was safe because of RLS
        query += ` AND (o.order_number ILIKE '%${searchTerm}%' OR c.name ILIKE '%${searchTerm}%')`;
      }

      if (status) {
        params.push(status);
        query += ` AND o.status = $${paramIndex++}`;
      }

      query += ` ORDER BY o.created_at DESC LIMIT 50`;

      const result = await client.query(query, params);
      return result.rows;
    } finally {
      client.release();
    }
  }

  async getOrderDetails(tenantId: string, orderId: string) {
    const client = await pool.connect();
    try {
      await client.query(`SET app.current_tenant = '${tenantId}'`);
      // This query is properly parameterized
      const result = await client.query(
        'SELECT * FROM orders WHERE id = $1',
        [orderId]
      );
      return result.rows[0];
    } finally {
      client.release();
    }
  }
}

@Controller('api/v1/orders')
export class OrdersController {
  constructor(private readonly ordersService: OrdersService) {}

  @Get('search')
  async searchOrders(
    @Req() req: any,
    @Query('q') searchTerm: string,
    @Query('status') status: string,
  ) {
    const tenantId = req.tenantId;
    if (!tenantId) {
      throw new Error('Tenant context required');
    }
    return this.ordersService.searchOrders(tenantId, searchTerm, status);
  }

  @Get(':id')
  async getOrder(@Req() req: any, @Query('id') orderId: string) {
    const tenantId = req.tenantId;
    if (!tenantId) {
      throw new Error('Tenant context required');
    }
    return this.ordersService.getOrderDetails(tenantId, orderId);
  }
}

@Module({
  controllers: [OrdersController],
  providers: [OrdersService],
})
export class OrdersModule {}
